#pragma once
// UE4 FSerializedShaderArchive version 2. Every payload passed here must be
// generated by Kadan. The writer has no source-archive or donor-copy operation.
#include "native_custom_backend_archive.h"

namespace P4MapKit
{
namespace CustomMaterial
{
namespace NativeBackend
{
struct OwnedArchiveShader
{
    unsigned frequency = 3;
    Bytes payload;
};
struct OwnedArchiveMap
{
    Bytes hash;
    std::vector<OwnedArchiveShader> shaders;
};
struct OwnedShaderArchiveBundle
{
    Bytes archive;
    Json manifest;
};

inline void U64(Bytes& out, std::uint64_t value)
{
    U32(out, std::uint32_t(value));
    U32(out, std::uint32_t(value >> 32));
}

inline Bytes WriteOwnedShaderArchive(const std::vector<OwnedArchiveMap>& maps)
{
    if (maps.empty() || maps.size() > 1024)
        throw std::runtime_error("shader archive map limit");
    Bytes mapHashes, shaderHashes, mapEntries, shaderEntries, preloads, indices, payloads;
    std::map<Bytes, unsigned> unique;
    std::set<Bytes> mapNames;
    unsigned shaders = 0, places = 0;
    for (const auto& map : maps)
    {
        if (map.hash.size() != 20 || !mapNames.insert(map.hash).second || map.shaders.empty() ||
            map.shaders.size() > 4096)
            throw std::runtime_error("invalid or duplicate shader archive map");
        Append(mapHashes, map.hash);
        U32(mapEntries, places);
        U32(mapEntries, unsigned(map.shaders.size()));
        U32(mapEntries, places);
        U32(mapEntries, unsigned(map.shaders.size()));
        for (const auto& shader : map.shaders)
        {
            if (places >= 65536)
                throw std::runtime_error("shader archive index limit");
            if (shader.frequency > 5 || shader.payload.empty() || shader.payload.size() > (1u << 20))
                throw std::runtime_error("shader archive payload limit");
            auto identity = Sha1(shader.payload);
            Bytes key = identity;
            key.push_back(std::uint8_t(shader.frequency));
            auto found = unique.find(key);
            unsigned index;
            if (found == unique.end())
            {
                if (shaders >= 65536 || payloads.size() + shader.payload.size() > (1u << 28))
                    throw std::runtime_error("shader archive output limit");
                index = shaders++;
                unique.emplace(std::move(key), index);
                Append(shaderHashes, identity);
                U64(shaderEntries, payloads.size());
                U32(shaderEntries, unsigned(shader.payload.size()));
                U32(shaderEntries, unsigned(shader.payload.size()));
                shaderEntries.push_back(std::uint8_t(shader.frequency));
                Append(payloads, shader.payload);
            }
            else
                index = found->second;
            const std::size_t entry = std::size_t(index) * 17;
            const auto offset =
                std::uint64_t(Read32(shaderEntries, entry)) | (std::uint64_t(Read32(shaderEntries, entry + 4)) << 32);
            U64(preloads, offset);
            U64(preloads, shader.payload.size());
            U32(indices, index);
            ++places;
        }
    }
    Bytes out;
    U32(out, 2);
    const Bytes* arrays[] = {&mapHashes, &shaderHashes, &mapEntries, &shaderEntries, &preloads, &indices};
    const unsigned counts[] = {unsigned(maps.size()), shaders, unsigned(maps.size()), shaders, places, places};
    std::uint64_t outputSize = 28 + payloads.size();
    for (const auto array : arrays)
        outputSize += array->size();
    if (outputSize > (1u << 28))
        throw std::runtime_error("shader archive output limit");
    for (unsigned i = 0; i != 6; ++i)
    {
        U32(out, counts[i]);
        Append(out, *arrays[i]);
    }
    Append(out, payloads);
    return out;
}

// Metadata is part of mod.json. The archive contains only newly compiled pixel
// programs. A game's vertex shaders remain in the player's stock library and
// are supplied by the existing material map when Tsuchi applies these entries.
// `format` is the game family's shader format (core/game_builds.h): GLSL_SWITCH, or SF_GLSL_SAGE for Switch 2,
// whose payloads must then come from the Ampere backend (compiler/ampere_write.cpp).
inline OwnedShaderArchiveBundle BuildOwnedShaderArchiveBundle(const std::vector<SetMaterial>& materials,
                                                              const std::string& library,
                                                              const std::string& format = "GLSL_SWITCH")
{
    if (format != "GLSL_SWITCH" && format != "SF_GLSL_SAGE")
        throw std::runtime_error("shader library format unknown");
    if (!Plain(library, 63))
        throw std::runtime_error("shader library name invalid");
    for (const unsigned char c : library)
        if (!std::isalnum(c) && c != '_')
            throw std::runtime_error("shader library name invalid");
    // The established serializer checks map positions, paths and content edits.
    (void)WriteShaderSet3(materials);
    OwnedShaderArchiveBundle out;
    out.manifest = Json::MakeObject();
    out.manifest["library"] = Json(library);
    out.manifest["archive"] = Json("ShaderArchive-" + library + "-" + format + ".ushaderbytecode");
    out.manifest["materials"] = Json::MakeArray();
    std::vector<OwnedArchiveMap> maps;
    for (const auto& material : materials)
    {
        OwnedArchiveMap map;
        Json row = Json::MakeObject();
        row["material"] = Json(material.material);
        row["game_material"] = Json(material.game_material);
        row["map_id"] = Json(Hex(material.map_id_hash));
        row["map_shaders"] = Json(double(material.map_shaders));
        row["shaders"] = Json::MakeArray();
        Bytes identities;
        for (const auto& shader : material.shaders)
        {
            const auto hash = Sha1(shader.payload);
            Append(identities, hash);
            map.shaders.push_back({3, shader.payload});
            Json entry = Json::MakeObject();
            entry["place"] = Json(double(shader.place));
            entry["hash"] = Json(Hex(hash));
            row["shaders"].array.push_back(entry);
        }
        map.hash = Sha1(identities);
        // An archive map is a generated-program collection, not a complete
        // replacement for the game's mixed-stage material map.
        row["archive_map"] = Json(Hex(map.hash));
        const auto& edits = material.edits;
        if (edits.old_size)
        {
            Json content = Json::MakeObject();
            content["old_size"] = Json(double(edits.old_size));
            content["new_size"] = Json(double(edits.new_size));
            content["operations"] = Json::MakeArray();
            for (const auto& operation : edits.operations)
            {
                Json op = Json::MakeObject();
                if (operation.copy)
                {
                    op["offset"] = Json(double(operation.offset));
                    op["length"] = Json(double(operation.length));
                }
                else
                    op["bytes"] = Json(Hex(operation.own));
                content["operations"].array.push_back(op);
            }
            content["names"] = Json::MakeArray();
            for (const auto& name : edits.names)
            {
                Json entry = Json::MakeObject();
                entry["name"] = Json(name.name);
                entry["number"] = Json(double(name.number));
                entry["offsets"] = Json::MakeArray();
                for (const auto offset : name.offsets)
                    entry["offsets"].array.push_back(Json(double(offset)));
                content["names"].array.push_back(entry);
            }
            row["content"] = content;
        }
        // Different materials may compile identical programs. Their common
        // archive collection is stored once, while each retains its map places.
        if (std::none_of(maps.begin(), maps.end(), [&](const OwnedArchiveMap& old) { return old.hash == map.hash; }))
            maps.push_back(std::move(map));
        out.manifest["materials"].array.push_back(row);
    }
    out.archive = WriteOwnedShaderArchive(maps);
    return out;
}
}
}
}
